package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="rr_evaluator_assignment",uniqueConstraints=@UniqueConstraint(name="uk_rr_evaluator_employee",columnNames={"agency_id","evaluation_case_id","employee_no"}))
public class RrEvaluatorAssignment extends RspAuditedEntity{public enum Status{ASSIGNED,RECUSED,REPLACED,SUBMITTED}@Column(name="evaluation_case_id",nullable=false,length=36)private String evaluationCaseId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="display_name",nullable=false,length=250)private String displayName;@Column(name="position_title",nullable=false,length=250)private String positionTitle;@Column(name="member_role",nullable=false,length=30)private String memberRole;@Column(name="voting_member",nullable=false)private boolean votingMember;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="conflict_declared",nullable=false)private boolean conflictDeclared;@Column(name="conflict_reason",length=2000)private String conflictReason;@Column(name="replacement_assignment_id",length=36)private String replacementAssignmentId;@Column(name="attending",nullable=false)private boolean attending;@Column(name="total_score",precision=10,scale=4)private BigDecimal totalScore;@Column(name="submitted_at")private Instant submittedAt;protected RrEvaluatorAssignment(){}public RrEvaluatorAssignment(String a,String c,RrCommitteeMember m){super(a);evaluationCaseId=requiredText(c,"evaluationCaseId");employeeNo=requiredText(m.getEmployeeNo(),"employeeNo");displayName=requiredText(m.getDisplayName(),"displayName");positionTitle=requiredText(m.getPositionTitle(),"positionTitle");memberRole=m.getMemberRole().name();votingMember=m.isVotingMember();status=Status.ASSIGNED;}public void conflict(String reason){if(status!=Status.ASSIGNED)throw new IllegalLifecycleTransitionException("Only an active assignment may declare conflict");conflictDeclared=true;conflictReason=requiredText(reason,"reason");status=Status.RECUSED;}public void replaceWith(String id){if(status!=Status.RECUSED)throw new IllegalLifecycleTransitionException("Only a recused assignment may be replaced");replacementAssignmentId=requiredText(id,"replacementAssignmentId");status=Status.REPLACED;}public void submit(BigDecimal score,boolean attending,Instant at){if(status!=Status.ASSIGNED||conflictDeclared)throw new IllegalLifecycleTransitionException("Only a non-conflicted active evaluator may submit");totalScore=score;this.attending=attending;submittedAt=at;status=Status.SUBMITTED;}public String getEvaluationCaseId(){return evaluationCaseId;}public String getEmployeeNo(){return employeeNo;}public String getDisplayName(){return displayName;}public String getPositionTitle(){return positionTitle;}public String getMemberRole(){return memberRole;}public boolean isVotingMember(){return votingMember;}public Status getStatus(){return status;}public boolean isConflictDeclared(){return conflictDeclared;}public String getConflictReason(){return conflictReason;}public String getReplacementAssignmentId(){return replacementAssignmentId;}public boolean isAttending(){return attending;}public BigDecimal getTotalScore(){return totalScore;}public Instant getSubmittedAt(){return submittedAt;}}
